function minimumPairRemoval(nums) {
  const values = [...nums];
  let operations = 0;
  const isSorted = () => values.every((value, i) => i === 0 || values[i - 1] <= value);
  while (!isSorted()) {
    let best = 0;
    for (let i = 1; i + 1 < values.length; i++) {
      if (values[i] + values[i + 1] < values[best] + values[best + 1]) {
        best = i;
      }
    }
    values.splice(best, 2, values[best] + values[best + 1]);
    operations++;
  }
  return operations;
}

