function minimumPairRemoval(nums) {
  // Recursive: stop when sorted, otherwise merge the leftmost smallest-sum pair and count one more.
  const sorted = nums.every((v, i) => i === 0 || nums[i - 1] <= v);
  if (sorted) return 0;
  const sums = nums.slice(1).map((v, i) => nums[i] + v);
  const at = sums.indexOf(Math.min(...sums));
  return 1 + minimumPairRemoval([...nums.slice(0, at), sums[at], ...nums.slice(at + 2)]);
}

