function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  // Small value ranges create many equal sums, which exercises the leftmost tie rule.
  const span = size === 'large' || rand() < 0.4 ? 1000 : 1 + Math.floor(rand() * 5);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  if (rand() < 0.15) nums.sort((a, b) => a - b);
  return [nums];
}
